/**
 * Clio's motion recipe as plain functions of time, so a given clock always gives the same frame. The React hooks in
 * theme.tsx drive these from requestAnimationFrame; tests call them directly.
 */
import { CLIO_MOTION } from "./tokens";

/** Ease-out quart: quick off the mark, a long soft landing. 0 → 0, 1 → 1. */
export function clioEaseOut(t: number): number {
  const p = Math.min(1, Math.max(0, t));
  return 1 - (1 - p) ** 4;
}

export interface ClioCountUpOptions {
  /** Where the count starts. */
  from?: number;
  /** Where it lands, exactly. */
  to: number;
  /** Milliseconds from start to `to`. */
  duration?: number;
  /** Decimal places shown on the way. */
  decimals?: number;
}

/** The value a count-up shows `elapsed` ms after it starts: `from` before, eased on the way, exactly `to` at the end. */
export function clioCountUp(
  elapsed: number,
  { from = 0, to, duration = CLIO_MOTION.alive.duration, decimals = 0 }: ClioCountUpOptions,
): number {
  if (!Number.isFinite(to)) return 0;
  if (!(duration > 0) || elapsed >= duration) return to;
  if (!(elapsed > 0)) return from;
  const scale = 10 ** Math.max(0, Math.min(6, Math.round(decimals)));
  const value = Math.round((from + (to - from) * clioEaseOut(elapsed / duration)) * scale) / scale;
  // Rounding never carries the count past where it lands.
  return to >= from ? Math.min(value, to) : Math.max(value, to);
}

/** A tile's place on a board: its row and column (any units, top-left of the tile). */
export interface ClioTilePosition {
  row: number;
  col: number;
}

/** Reading order: row by row, left to right. Returns the indices of `positions` in that order. */
export function clioRiseOrder(positions: readonly ClioTilePosition[]): number[] {
  return positions
    .map((position, index) => ({ ...position, index }))
    .sort((a, b) => a.row - b.row || a.col - b.col || a.index - b.index)
    .map((tile) => tile.index);
}

export interface ClioRiseOptions {
  /** Milliseconds between one tile and the next. */
  stagger?: number;
  /** Milliseconds before the first tile. */
  start?: number;
}

/**
 * The rise-in delay of each tile, by the tile's place in reading order. Pass a count for tiles already in reading
 * order (the usual DOM order), or positions for tiles placed on a grid in any order.
 */
export function clioRiseSchedule(
  tiles: number | readonly ClioTilePosition[],
  { stagger = CLIO_MOTION.rise.stagger, start = 0 }: ClioRiseOptions = {},
): number[] {
  if (typeof tiles === "number")
    return Array.from({ length: Math.max(0, Math.floor(tiles)) }, (_, i) => start + i * stagger);
  const delays: number[] = new Array(tiles.length).fill(0);
  clioRiseOrder(tiles).forEach((index, place) => {
    delays[index] = start + place * stagger;
  });
  return delays;
}

/** When a tile's alive moment begins: shortly after its rise starts. */
export const clioAliveDelay = (riseDelay: number) => riseDelay + CLIO_MOTION.alive.delay;

"use client";
/**
 * ClioTheme: the Clio scope. It writes the theme's custom properties (tokens.ts) onto its own wrapper, so everything
 * inside reads Clio values and nothing is injected globally. `mode` switches the whole subtree between paper and
 * focus; a ClioTile with `tone="focus"` takes the dark state on its own while the board stays paper.
 *
 * Inspired by Sean Galt (@seanaiux)'s minimal paper cards.
 */
import {
  type CSSProperties,
  createContext,
  type HTMLAttributes,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { clioAliveDelay, clioCountUp } from "./motion";
import { CLIO_MOTION, type ClioColors, type ClioMode, clioCssVariables } from "./tokens";

/** `auto` follows the reader's system setting; `reduce` and `full` decide for them (a recording, a test). */
export type ClioMotion = "auto" | "full" | "reduce";

/** Your own colours for either mode, laid over Clio's. */
export type ClioColorOverrides = Partial<Record<ClioMode, Partial<ClioColors>>>;

export interface ClioScopeValue {
  mode: ClioMode;
  motion: ClioMotion;
  colors?: ClioColorOverrides;
}

const ClioContext = createContext<ClioScopeValue | null>(null);

/** The mode, motion and colours of the nearest Clio scope, or null outside one. */
export function useClioTheme(): ClioScopeValue | null {
  return useContext(ClioContext);
}

const REDUCE = "(prefers-reduced-motion: reduce)";
const subscribeMotion = (onChange: () => void) => {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return () => {};
  const query = window.matchMedia(REDUCE);
  query.addEventListener?.("change", onChange);
  return () => query.removeEventListener?.("change", onChange);
};
const systemReduces = () =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia(REDUCE).matches;

/** True when motion should stay still: the scope says `reduce`, or it says `auto` and the reader asks for less. */
export function useClioReducedMotion(): boolean {
  const motion = useContext(ClioContext)?.motion ?? "auto";
  const system = useSyncExternalStore(subscribeMotion, systemReduces, () => false);
  return motion === "reduce" || (motion === "auto" && system);
}

/** False until `delay` ms after mount, then true; true at once when motion is reduced or `enabled` is false. */
export function useClioAlive(delay: number, enabled = true): boolean {
  const reduced = useClioReducedMotion();
  const still = reduced || !enabled;
  const [alive, setAlive] = useState(still);
  useEffect(() => {
    if (still) return setAlive(true);
    const timer = setTimeout(() => setAlive(true), Math.max(0, delay));
    return () => clearTimeout(timer);
  }, [still, delay]);
  return alive || still;
}

export interface ClioCountUpHookOptions {
  from?: number;
  duration?: number;
  /** Milliseconds before the first count starts. */
  delay?: number;
  decimals?: number;
  /** Off, the final value shows at once. */
  enabled?: boolean;
}

/**
 * The number a count-up shows now. It counts from `from` to `to` once, after `delay`, and eases to any later `to`
 * from wherever it is. Under reduced motion it is always `to`.
 */
export function useClioCountUp(
  to: number,
  {
    from = 0,
    duration = CLIO_MOTION.alive.duration,
    delay = 0,
    decimals = 0,
    enabled = true,
  }: ClioCountUpHookOptions = {},
): number {
  const reduced = useClioReducedMotion();
  const still = reduced || !enabled;
  const [value, setValue] = useState(still ? to : from);
  const shown = useRef(value);
  shown.current = value;
  // The first count waits for the tile's rise; a later change of `to` moves at once and quicker.
  const settled = useRef(false);
  useEffect(() => {
    if (still) {
      settled.current = true;
      setValue(to);
      return;
    }
    const first = !settled.current;
    const begin = first ? from : shown.current;
    const length = first ? duration : Math.min(duration, 620);
    if (begin === to) {
      settled.current = true;
      setValue(to);
      return;
    }
    let frame = 0;
    const start = performance.now() + (first ? Math.max(0, delay) : 0);
    const tick = (now: number) => {
      const elapsed = now - start;
      if (elapsed >= 0)
        setValue(clioCountUp(elapsed, { from: begin, to, duration: length, decimals }));
      if (elapsed < length) frame = requestAnimationFrame(tick);
      else settled.current = true;
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [to, still, from, delay, duration, decimals]);
  return still ? to : value;
}

const cx = (...parts: (string | false | null | undefined)[]) => parts.filter(Boolean).join(" ");

/** Shared rules for every Clio piece: the scope, the tile, captions, numerals and the rise-in. */
export const CLIO_BASE_CSS = `
.clio-scope{font-family:var(--clio-font);color:var(--clio-ink);-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;text-rendering:optimizeLegibility}
.clio-scope *,.clio-scope *::before,.clio-scope *::after{box-sizing:border-box}
.clio-scope[data-clio-surface]{background:var(--clio-canvas);transition:background-color var(--clio-mode-ms) var(--clio-mode-ease),color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-tile{position:relative;isolation:isolate;overflow:hidden;display:flex;flex-direction:column;min-width:0;margin:0;padding:var(--clio-pad);border-radius:var(--clio-radius);background:var(--clio-tile);color:var(--clio-ink);box-shadow:0 0 0 1px var(--clio-hairline),var(--clio-shadow);transition:background-color var(--clio-mode-ms) var(--clio-mode-ease),color var(--clio-mode-ms) var(--clio-mode-ease),box-shadow var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-tile[data-rise]{animation:clio-rise var(--clio-rise-ms) var(--clio-rise-ease) both;animation-delay:var(--clio-rise-delay,0ms)}
@keyframes clio-rise{from{opacity:0;transform:translate3d(0,var(--clio-rise-distance),0) scale(var(--clio-rise-scale))}to{opacity:1;transform:none}}
.clio-tile__glow{position:absolute;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(140% 100% at 0% 100%,var(--clio-glow),transparent 64%);opacity:0;transform:scale(.82);transform-origin:0% 100%;transition:opacity 700ms var(--clio-mode-ease),transform 900ms var(--clio-alive-ease)}
.clio-tile[data-glow] .clio-tile__glow{opacity:1;transform:none}
.clio-tile__head{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:16px}
.clio-caption{margin:0;font-family:var(--clio-mono);font-size:11px;font-weight:400;line-height:1.4;letter-spacing:0;color:var(--clio-ink-tertiary);transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-numeral{margin:0;font-family:var(--clio-font);font-weight:var(--clio-numeral-weight);letter-spacing:var(--clio-numeral-tracking);font-variant-numeric:tabular-nums;font-feature-settings:"tnum" 1;line-height:.92;color:var(--clio-numeral);transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-sr{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
:where(.clio-scope) button{font:inherit;color:inherit}
:where(.clio-scope) :focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
@media (prefers-reduced-motion:reduce){.clio-tile[data-rise]{animation:none}.clio-tile__glow{transition:opacity 200ms linear}}
`;

export interface ClioThemeProps extends HTMLAttributes<HTMLDivElement> {
  /** `paper` (light) or `focus` (dark) for everything inside. */
  mode?: ClioMode;
  /** Your own colours for either mode. */
  colors?: ClioColorOverrides;
  motion?: ClioMotion;
  /**
   * Paint the board: canvas colour, ink and the type. Off, the wrapper takes no box (display: contents) and only
   * carries the tokens.
   */
  surface?: boolean;
  children?: ReactNode;
}

export function ClioTheme({
  mode,
  colors,
  motion,
  surface = true,
  className,
  style,
  children,
  ...rest
}: ClioThemeProps) {
  const parent = useContext(ClioContext);
  const resolved: ClioScopeValue = useMemo(
    () => ({
      mode: mode ?? parent?.mode ?? "paper",
      motion: motion ?? parent?.motion ?? "auto",
      colors: colors ?? parent?.colors,
    }),
    [mode, motion, colors, parent?.mode, parent?.motion, parent?.colors],
  );
  const vars = useMemo(
    () => clioCssVariables(resolved.mode, resolved.colors?.[resolved.mode]) as CSSProperties,
    [resolved],
  );
  return (
    <ClioContext.Provider value={resolved}>
      <div
        {...rest}
        className={cx("clio-scope", className)}
        data-clio-mode={resolved.mode}
        data-clio-surface={surface ? "" : undefined}
        style={{
          ...vars,
          ...(surface
            ? { colorScheme: resolved.mode === "focus" ? "dark" : "light" }
            : { display: "contents" }),
          ...style,
        }}
      >
        {/* The outermost scope carries the shared rules once. */}
        {parent ? null : <style>{CLIO_BASE_CSS}</style>}
        {children}
      </div>
    </ClioContext.Provider>
  );
}

/** Inside a Clio scope this adds nothing; on its own a piece gets a scope of its own, so it always has its tokens. */
export function ClioScope({ children }: { children: ReactNode }) {
  return useContext(ClioContext) ? children : <ClioTheme surface={false}>{children}</ClioTheme>;
}

export interface ClioTileProps extends Omit<HTMLAttributes<HTMLElement>, "title"> {
  as?: "section" | "article" | "div" | "li";
  /** The caption at the top left, which also names the tile. */
  label?: ReactNode;
  /** A caption at the top right. */
  meta?: ReactNode;
  /** The element the label renders as. */
  labelAs?: "h2" | "h3" | "h4" | "p";
  /** `focus` gives this tile the dark state on its own; `inherit` follows the board. */
  tone?: ClioMode | "inherit";
  /** The light gathered in a focus tile's corner. On by default for a focus tile. */
  glow?: boolean;
  /** Rise in on mount. */
  rise?: boolean;
  /** The tile's place in its board's stagger (reading order). */
  riseIndex?: number;
  /** Milliseconds before it rises; wins over `riseIndex`. */
  riseDelay?: number;
  children?: ReactNode;
}

/** The delay a tile rises after, from its index or an explicit delay. */
export const clioTileDelay = (riseIndex?: number, riseDelay?: number) =>
  riseDelay ?? (riseIndex ?? 0) * CLIO_MOTION.rise.stagger;
/** When a tile's own alive moment starts. */
export const clioTileAliveDelay = (riseIndex?: number, riseDelay?: number) =>
  clioAliveDelay(clioTileDelay(riseIndex, riseDelay));

/** A paper tile: the shell every Clio widget sits in. On its own it brings a scope, so it always has its tokens. */
export function ClioTile(props: ClioTileProps) {
  return useContext(ClioContext) ? (
    <TileInScope {...props} />
  ) : (
    <ClioTheme surface={false}>
      <TileInScope {...props} />
    </ClioTheme>
  );
}

function TileInScope({
  as: Tag = "section",
  label,
  meta,
  labelAs: Label = "h3",
  tone = "inherit",
  glow,
  rise = true,
  riseIndex,
  riseDelay,
  className,
  style,
  children,
  ...rest
}: ClioTileProps) {
  const scope = useContext(ClioContext) as ClioScopeValue;
  const reduced = useClioReducedMotion();
  const id = useId();
  const own = tone !== "inherit" ? tone : null;
  const mode: ClioMode = own ?? scope.mode;
  const lit = glow ?? mode === "focus";
  // The tile always sits in a provider, so turning its own tone on or off changes values, never the tree: the tile
  // and what's inside it (a switch with focus, say) stay mounted and change colour in place.
  const value = useMemo<ClioScopeValue>(
    () => (own ? { mode: own, motion: scope.motion, colors: scope.colors } : scope),
    [own, scope],
  );
  // A tile with its own tone carries that mode's tokens on itself.
  const vars = useMemo(
    () => (own ? (clioCssVariables(own, scope.colors?.[own]) as CSSProperties) : null),
    [own, scope.colors],
  );
  const delay = clioTileDelay(riseIndex, riseDelay);
  return (
    <ClioContext.Provider value={value}>
      <Tag
        {...rest}
        className={cx("clio-tile", className)}
        aria-labelledby={label ? `${id}-label` : undefined}
        data-clio-tone={mode}
        data-rise={rise && !reduced ? "" : undefined}
        data-glow={lit && mode === "focus" ? "" : undefined}
        style={{ ...vars, ["--clio-rise-delay" as string]: `${delay}ms`, ...style }}
      >
        <span className="clio-tile__glow" aria-hidden="true" />
        {label || meta ? (
          <div className="clio-tile__head">
            {label ? (
              <Label id={`${id}-label`} className="clio-caption">
                {label}
              </Label>
            ) : (
              <span />
            )}
            {meta ? <span className="clio-caption">{meta}</span> : null}
          </div>
        ) : null}
        {children}
      </Tag>
    </ClioContext.Provider>
  );
}

/**
 * Clio, the muse who keeps the scroll: quiet paper boards of small live widgets. This module is the single source of
 * truth for the theme, as plain data: the paper and focus palettes, shape, type, the motion recipe and the text pairs
 * the contrast test checks. ClioTheme (theme.tsx) writes these onto its own wrapper as `--clio-*` custom properties;
 * nothing is injected globally.
 *
 * Inspired by Sean Galt (@seanaiux)'s minimal paper cards. The values here are our own, tuned by eye and by the
 * contrast test, never sampled from the reference.
 *
 * Fonts are free (SIL OFL) and named with fallbacks; load them yourself: Geist for numerals and labels, Geist Mono
 * for captions.
 */

export const CLIO_MODES = ["paper", "focus"] as const;
/** `paper` is the light board; `focus` the dark one, for a whole board or a single active tile. */
export type ClioMode = (typeof CLIO_MODES)[number];

/** Every colour Clio names. All of them are opaque except `glow`, which is light laid over a focus tile. */
export interface ClioColors {
  /** The board under the tiles. */
  canvas: string;
  /** A tile's paper. */
  tile: string;
  /** Paper lifted off a tile: the next row, a chip, a cover. */
  raised: string;
  /** A tile's edge. */
  hairline: string;
  /** Dividers and rules inside a tile. */
  hairlineStrong: string;
  /** Text and icons. */
  ink: string;
  inkSecondary: string;
  /** Captions: small, mono, still at least 4.5:1. */
  inkTertiary: string;
  /** Large thin numerals (at least 3:1). */
  numeral: string;
  /** Neutral data marks: bars, ticks, a cover's lines. */
  bar: string;
  /** The empty part of a bar, ring or progress line. */
  track: string;
  /** The one accent, ultramarine: it marks what is current (today, next, on, playing). */
  accent: string;
  accentHover: string;
  accentPressed: string;
  /** Text and icons on an accent fill. */
  onAccent: string;
  /** The accent as text or a thin line on a surface. */
  accentInk: string;
  /** A wash of the accent behind the current row. */
  accentSoft: string;
  /** The light that gathers in a focus tile's corner. */
  glow: string;
}

export const CLIO_PAPER: ClioColors = {
  canvas: "#E4E3DF",
  tile: "#FAF9F6",
  raised: "#FFFFFF",
  hairline: "#DFDEDA",
  hairlineStrong: "#CFCDC9",
  ink: "#1B1E28",
  inkSecondary: "#4D4F58",
  inkTertiary: "#61636A",
  numeral: "#1B1E28",
  bar: "#4A4D55",
  track: "#E4E3DF",
  accent: "#2039DD",
  accentHover: "#192DC1",
  accentPressed: "#1323A3",
  onAccent: "#FFFFFF",
  accentInk: "#2039DD",
  accentSoft: "#E6EDFC",
  glow: "rgb(32 57 221 / 0.42)",
};

export const CLIO_FOCUS: ClioColors = {
  canvas: "#0E111B",
  tile: "#171A26",
  raised: "#202431",
  hairline: "#2A2D39",
  hairlineStrong: "#3E424E",
  ink: "#F4F3F1",
  inkSecondary: "#C2C4CB",
  inkTertiary: "#A1A4AE",
  numeral: "#F4F3F1",
  bar: "#B5B7BD",
  track: "#2C303C",
  accent: "#3155F1",
  accentHover: "#3960F4",
  accentPressed: "#2848D7",
  onAccent: "#FFFFFF",
  accentInk: "#8AABFD",
  accentSoft: "#1D2B53",
  glow: "rgb(49 85 241 / 0.55)",
};

export const CLIO_COLORS: Readonly<Record<ClioMode, ClioColors>> = {
  paper: CLIO_PAPER,
  focus: CLIO_FOCUS,
};

/** Soft shadows tuned for paper; the hairline edge is drawn separately. */
export const CLIO_SHADOWS: Readonly<Record<ClioMode, { tile: string; raised: string }>> = {
  paper: {
    tile: "0 1px 1px rgb(27 30 40 / 0.04), 0 12px 28px -16px rgb(27 30 40 / 0.2)",
    raised: "0 1px 2px rgb(27 30 40 / 0.07), 0 6px 14px -8px rgb(27 30 40 / 0.22)",
  },
  focus: {
    tile: "0 1px 1px rgb(0 0 0 / 0.3), 0 16px 36px -20px rgb(0 0 0 / 0.75)",
    raised: "0 1px 2px rgb(0 0 0 / 0.4), 0 8px 18px -10px rgb(0 0 0 / 0.6)",
  },
};

export interface ClioShape {
  /** A tile's corner. */
  radius: number;
  /** Rows, chips' wells and covers inside a tile. */
  radiusInner: number;
  /** A tile's padding. */
  padding: number;
  /** Space between tiles on a board. */
  gap: number;
}

export const CLIO_SHAPE: ClioShape = { radius: 20, radiusInner: 12, padding: 16, gap: 14 };

/** Each family with its fallbacks. Consumers load the fonts themselves. */
export const CLIO_FONTS = {
  sans: '"Geist", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif',
  mono: '"Geist Mono", ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace',
} as const;

/** The type roles. Numerals are thin with tabular figures; captions are small mono in sentence case, never capitals. */
export const CLIO_TYPE = {
  numeral: { family: "sans", weight: 200, tracking: "-0.045em", sizes: { lg: 56, md: 40, sm: 26 } },
  label: { family: "sans", weight: 500, size: 13, tracking: "-0.006em" },
  body: { family: "sans", weight: 400, size: 13, tracking: "-0.003em" },
  caption: { family: "mono", weight: 400, size: 11, tracking: "0" },
} as const;

/**
 * The motion recipe. On mount the tiles rise in, one after another in reading order; each tile then has its own
 * alive moment (a count-up, bars growing, a ring filling, a playhead moving). Reduced motion keeps none of it: no
 * rise, no loops, final values at once.
 */
export const CLIO_MOTION = {
  rise: {
    duration: 720,
    distance: 18,
    scale: 0.97,
    stagger: 70,
    ease: "cubic-bezier(0.22, 1, 0.36, 1)",
  },
  /** Starts this long after a tile's rise begins, so the two read as one movement. */
  alive: { delay: 320, duration: 1100, stagger: 55, ease: "cubic-bezier(0.16, 1, 0.3, 1)" },
  /** Paper to focus and back, for a board or a tile. */
  mode: { duration: 520, ease: "cubic-bezier(0.4, 0, 0.2, 1)" },
  press: { duration: 160, ease: "cubic-bezier(0.3, 0.7, 0.4, 1)" },
} as const;

/** Text (or a mark that must read) and the surface it sits on, with the least contrast it needs. */
export interface ClioTextPair {
  text: keyof ClioColors;
  on: keyof ClioColors;
  min: number;
}

const onSurfaces = (text: keyof ClioColors, min: number): ClioTextPair[] =>
  (["canvas", "tile", "raised"] as const).map((on) => ({ text, on, min }));

/** Every text and surface pair Clio draws, in either mode. The contrast test holds both palettes to these. */
export const CLIO_TEXT_PAIRS: readonly ClioTextPair[] = [
  ...onSurfaces("ink", 4.5),
  ...onSurfaces("inkSecondary", 4.5),
  ...onSurfaces("inkTertiary", 4.5),
  ...onSurfaces("accentInk", 4.5),
  ...onSurfaces("numeral", 3),
  { text: "ink", on: "accentSoft", min: 4.5 },
  { text: "inkTertiary", on: "accentSoft", min: 4.5 },
  { text: "accentInk", on: "accentSoft", min: 4.5 },
  { text: "onAccent", on: "accent", min: 4.5 },
  { text: "onAccent", on: "accentHover", min: 4.5 },
  { text: "onAccent", on: "accentPressed", min: 4.5 },
  // Marks that carry meaning, drawn on a tile: bars, the ring's arc, today's bar, the playhead.
  { text: "bar", on: "tile", min: 3 },
  { text: "accent", on: "tile", min: 3 },
];

/** `#rgb` or `#rrggbb` to 0–255 channels. */
function channels(hex: string): [number, number, number] {
  const h = hex.trim().replace(/^#/, "");
  const full = h.length === 3 ? [...h].map((c) => c + c).join("") : h;
  if (!/^[0-9a-f]{6}$/i.test(full))
    throw new Error(`Clio contrast needs an opaque hex colour, got ${hex}`);
  const n = Number.parseInt(full, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/** WCAG 2 relative luminance of an opaque hex colour. */
export function clioLuminance(hex: string): number {
  const [r, g, b] = channels(hex).map((v) => {
    const c = v / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  }) as [number, number, number];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** WCAG 2 contrast ratio between two opaque hex colours, from 1 to 21. */
export function clioContrastRatio(a: string, b: string): number {
  const [hi, lo] = [clioLuminance(a), clioLuminance(b)].sort((x, y) => y - x) as [number, number];
  return (hi + 0.05) / (lo + 0.05);
}

/** A mode's colours with your own on top. */
export function clioColors(mode: ClioMode = "paper", overrides?: Partial<ClioColors>): ClioColors {
  return { ...CLIO_COLORS[mode], ...overrides };
}

const kebab = (key: string) => key.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);

/** The custom properties ClioTheme writes on its wrapper, e.g. `--clio-ink`, `--clio-radius`. */
export function clioCssVariables(
  mode: ClioMode = "paper",
  overrides?: Partial<ClioColors>,
): Record<`--clio-${string}`, string> {
  const out: Record<`--clio-${string}`, string> = {};
  for (const [key, value] of Object.entries(clioColors(mode, overrides)))
    out[`--clio-${kebab(key)}`] = value;
  out["--clio-shadow"] = CLIO_SHADOWS[mode].tile;
  out["--clio-shadow-raised"] = CLIO_SHADOWS[mode].raised;
  out["--clio-radius"] = `${CLIO_SHAPE.radius}px`;
  out["--clio-radius-inner"] = `${CLIO_SHAPE.radiusInner}px`;
  out["--clio-pad"] = `${CLIO_SHAPE.padding}px`;
  out["--clio-gap"] = `${CLIO_SHAPE.gap}px`;
  out["--clio-font"] = CLIO_FONTS.sans;
  out["--clio-mono"] = CLIO_FONTS.mono;
  out["--clio-numeral-weight"] = String(CLIO_TYPE.numeral.weight);
  out["--clio-numeral-tracking"] = CLIO_TYPE.numeral.tracking;
  out["--clio-rise-ms"] = `${CLIO_MOTION.rise.duration}ms`;
  out["--clio-rise-ease"] = CLIO_MOTION.rise.ease;
  out["--clio-rise-distance"] = `${CLIO_MOTION.rise.distance}px`;
  out["--clio-rise-scale"] = String(CLIO_MOTION.rise.scale);
  out["--clio-alive-ms"] = `${CLIO_MOTION.alive.duration}ms`;
  out["--clio-alive-ease"] = CLIO_MOTION.alive.ease;
  out["--clio-mode-ms"] = `${CLIO_MOTION.mode.duration}ms`;
  out["--clio-mode-ease"] = CLIO_MOTION.mode.ease;
  out["--clio-press-ms"] = `${CLIO_MOTION.press.duration}ms`;
  out["--clio-press-ease"] = CLIO_MOTION.press.ease;
  return out;
}
